#!/usr/bin/env node
/**
 * Refreshes the vendored copies of the integrations service's public contract.
 *
 *   node scripts/refresh-contract.mjs [--spec <path-or-url>] [--service <base-url>]
 *
 * Two independent artifacts:
 *
 *   contract/integrations-v1.json
 *     Converted from the service's OpenAPI 3.1 spec. That spec is generated by
 *     Scribe (`php artisan docs:generate`) and regenerated by the integrations
 *     repo's CI on every push to main, so it tracks the real routes. Stored as
 *     JSON so tests need no YAML parser at run time.
 *     Deliberately NOT in package.json `files`: it is a test-time artifact, and
 *     357 KB has no business in the published tarball. The one runtime value it
 *     implies — the API version the mock reports — is the API_VERSION constant in
 *     src/http.ts, which tests/contract.test.ts asserts against this snapshot.
 *
 *   assets/schemas/<domain>-<version>.json
 *     The JSON schemas the mock serves at GET /schemas/{domain}/{version}.
 *     These only exist behind a RUNNING service (they are PHP classes in
 *     app/Support/Schema/Versions/**, not files), so this half needs --service
 *     pointing at a reachable instance and is skipped otherwise.
 *
 * Defaults assume the sibling checkout layout of the revenexx monorepo.
 */

import { mkdirSync, readFileSync, writeFileSync } from 'node:fs';
import { dirname, join, resolve } from 'node:path';
import { fileURLToPath } from 'node:url';
import { parse as parseYaml } from 'yaml';

const REPO = resolve(dirname(fileURLToPath(import.meta.url)), '..');
const DEFAULT_SPEC = resolve(REPO, '../../../services/integrations/docs/api/openapi.yaml');
const DEFAULT_SERVICE = 'https://integrations.rvnxx.test/api/v1';

/** Domains/versions to snapshot. Mirrors app/Support/Schema/SchemaRegistry.php. */
const SCHEMA_TARGETS = [
  ['node', 'v0-draft'],
  ['credential', 'v0-draft'],
  ['template', 'v0-draft'],
  ['workflow', 'v0-draft'],
];

function parseArgs(argv) {
  const out = { spec: DEFAULT_SPEC, service: null };
  for (let i = 0; i < argv.length; i += 1) {
    if (argv[i] === '--spec') out.spec = argv[++i];
    else if (argv[i] === '--service') out.service = argv[++i] ?? DEFAULT_SERVICE;
    else if (argv[i] === '--help' || argv[i] === '-h') {
      console.log('Usage: node scripts/refresh-contract.mjs [--spec <path-or-url>] [--service <base-url>]');
      process.exit(0);
    }
  }
  return out;
}

async function readSpec(location) {
  if (/^https?:\/\//.test(location)) {
    const res = await fetch(location);
    if (!res.ok) throw new Error(`GET ${location} → ${res.status}`);
    return await res.text();
  }
  return readFileSync(location, 'utf-8');
}

async function refreshSpec(location) {
  const raw = await readSpec(location);
  const spec = location.endsWith('.json') ? JSON.parse(raw) : parseYaml(raw);
  const pathCount = Object.keys(spec.paths ?? {}).length;
  if (!spec.openapi || pathCount === 0) {
    throw new Error(`${location} does not look like an OpenAPI document (openapi=${spec.openapi}, paths=${pathCount}).`);
  }

  const target = join(REPO, 'contract/integrations-v1.json');
  mkdirSync(dirname(target), { recursive: true });
  // `x-devkit-*` records where this copy came from; the contract test reports the
  // version so a mismatch is traceable rather than mysterious.
  const out = {
    'x-devkit-source': location.replace(/^.*\/services\//, 'services/'),
    'x-devkit-fetched': new Date().toISOString().slice(0, 10),
    ...spec,
  };
  writeFileSync(target, `${JSON.stringify(out, null, 2)}\n`, 'utf-8');
  console.log(`openapi   ${spec.openapi}, info.version ${spec.info?.version}, ${pathCount} paths → contract/integrations-v1.json`);
}

async function refreshSchemas(base) {
  let written = 0;
  for (const [domain, version] of SCHEMA_TARGETS) {
    const url = `${base.replace(/\/$/, '')}/schemas/${domain}/${version}`;
    let res;
    try {
      res = await fetch(url);
    } catch (err) {
      console.warn(`schemas   SKIP ${domain}/${version} — ${base} unreachable (${err.message})`);
      return written;
    }
    if (!res.ok) {
      console.warn(`schemas   SKIP ${domain}/${version} — GET ${url} → ${res.status}`);
      continue;
    }
    const body = await res.json();
    // The endpoint wraps the schema: { domain, version, schema: {...} }. The mock
    // serves the schema itself, so store the inner document.
    const schema = body?.schema ?? body;
    const target = join(REPO, 'assets/schemas', `${domain}-${version}.json`);
    mkdirSync(dirname(target), { recursive: true });
    writeFileSync(target, `${JSON.stringify(schema, null, 2)}\n`, 'utf-8');
    console.log(`schemas   ${domain}/${version} → assets/schemas/${domain}-${version}.json`);
    written += 1;
  }
  return written;
}

const args = parseArgs(process.argv.slice(2));
await refreshSpec(args.spec);
if (args.service) {
  const n = await refreshSchemas(args.service);
  if (n === 0) {
    console.warn('\nNo schemas written. They need a running integrations service; see assets/schemas/README.md.');
  }
} else {
  console.log('schemas   skipped (pass --service <base-url> against a running instance to refresh them)');
}
